public function isConstWithoutType(Tokens $tokens, int $index): bool
{
    $index = $tokens->getNextMeaningfulToken($index);

    return $tokens[$index]->isGivenKind(T_STRING) && $tokens[$tokens->getNextMeaningfulToken($index)]->equals('=');
}

public function fixClassConstantNativeTypes(Tokens $tokens, int $index): void
{
    $this->hydrateClassConstantTypeCatalog();

    foreach ($this->collectNativeTypeHintIndexesForConstant($tokens, $index) as $nativeTypeHintIndex) {
        $this->rewriteNativeTypeHintToken($tokens, $nativeTypeHintIndex, $this->classConstantTypeCatalog);
    }
}

/**
