public function fixPropertyNativeTypes(Tokens $tokens, int $index, array $beforePropertyTypeTokens): void
{
    $this->hydrateClassPropertyTypeCatalog();

    foreach ($this->collectNativeTypeHintIndexesForProperty($tokens, $index, $beforePropertyTypeTokens) as $nativeTypeHintIndex) {
        $this->rewriteNativeTypeHintToken($tokens, $nativeTypeHintIndex, $this->classPropertyTypeCatalog);
    }
}

/**
