public function getInternalClassNames(): array
{
    if ([] === $this->internalClassNameCatalog) {
        $classes = [];

        foreach (get_declared_classes() as $class) {
            if ((new \ReflectionClass($class))->isInternal()) {
                $classes[strtolower($class)] = $class;
            }
        }

        $this->internalClassNameCatalog = $classes;
    }

    return $this->internalClassNameCatalog;
}

/**
 * @param array<string, true>   $uses
 * @param array<string, string> $classNames
 */
public function fixClassReferencesInNamespace(Tokens $tokens, NamespaceAnalysis $namespace, array $uses, array $classNames): void
{
    foreach ($this->collectClassReferenceIndexes($tokens, $namespace) as $reference) {
        $currentContent = $tokens[$reference]->getContent();
        $lowerCurrentContent = strtolower($currentContent);

        if (isset($classNames[$lowerCurrentContent]) && $currentContent !== $classNames[$lowerCurrentContent] && !isset($uses[$lowerCurrentContent])) {
            $tokens[$reference] = new Token([T_STRING, $classNames[$lowerCurrentContent]]);
        }
    }
}

